<?php
if (!defined('ABSPATH')) { exit; }
final class SPF_Admin {
 public function hooks(){add_action('admin_menu',[$this,'menu']);add_action('admin_enqueue_scripts',[$this,'assets']);add_action('admin_init',[$this,'save_settings']);}
 public function menu(){add_menu_page(__('Sistema para Farmacias','sistema-para-farmacias'),__('Farmacias','sistema-para-farmacias'),SPF_Roles::ACCESS,'sistema-para-farmacias',[$this,'render_dashboard'],'dashicons-store',26);add_submenu_page('sistema-para-farmacias',__('Dashboard','sistema-para-farmacias'),__('Dashboard','sistema-para-farmacias'),SPF_Roles::ACCESS,'sistema-para-farmacias',[$this,'render_dashboard']);add_submenu_page('sistema-para-farmacias',__('Productos','sistema-para-farmacias'),__('Productos','sistema-para-farmacias'),SPF_Roles::PRODUCTS,'spf-products',[$this,'render_products']);add_submenu_page('sistema-para-farmacias',__('Inventario / Lotes','sistema-para-farmacias'),__('Inventario / Lotes','sistema-para-farmacias'),SPF_Roles::INVENTORY,'spf-inventory',[$this,'render_inventory']);add_submenu_page('sistema-para-farmacias',__('Punto de venta','sistema-para-farmacias'),__('Punto de venta','sistema-para-farmacias'),SPF_Roles::SELL,'spf-pos',[$this,'render_pos']);add_submenu_page('sistema-para-farmacias',__('Ventas','sistema-para-farmacias'),__('Ventas','sistema-para-farmacias'),SPF_Roles::SALES,'spf-sales',[$this,'render_sales']);add_submenu_page('sistema-para-farmacias',__('Clientes','sistema-para-farmacias'),__('Clientes','sistema-para-farmacias'),SPF_Roles::CUSTOMERS,'spf-customers',[$this,'render_customers']);add_submenu_page('sistema-para-farmacias',__('Comprobantes','sistema-para-farmacias'),__('Comprobantes','sistema-para-farmacias'),SPF_Roles::INVOICES,'spf-documents',[$this,'render_documents']);add_submenu_page('sistema-para-farmacias',__('Configuración','sistema-para-farmacias'),__('Configuración','sistema-para-farmacias'),SPF_Roles::SETTINGS,'spf-settings',[$this,'render_settings']);add_submenu_page('sistema-para-farmacias',__('Roles y permisos','sistema-para-farmacias'),__('Roles y permisos','sistema-para-farmacias'),SPF_Roles::USERS,'spf-roles',[$this,'render_roles']);}
 public function assets($hook){if(strpos((string)$hook,'sistema-para-farmacias')===false&&strpos((string)$hook,'spf-')===false){return;}wp_enqueue_style('spf-admin',SPF_PLUGIN_URL.'assets/css/admin.css',[],SPF_VERSION);wp_enqueue_script('spf-admin',SPF_PLUGIN_URL.'assets/js/admin.js',['jquery'],SPF_VERSION,true);wp_enqueue_script('spf-scanner',SPF_PLUGIN_URL.'assets/js/scanner.js',[],SPF_VERSION,true);wp_localize_script('spf-scanner','SPFAdmin',['ajax_url'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('spf_nonce')]);}
 private function can_settings(){return current_user_can(SPF_Roles::SETTINGS)||current_user_can('manage_options');}
 public function save_settings(){if(isset($_POST['spf_save_country'])){if(!$this->can_settings()){wp_die(esc_html__('No tienes permisos para cambiar esta configuración.','sistema-para-farmacias'));}check_admin_referer('spf_save_country');$country=strtolower(sanitize_key(wp_unslash($_POST['spf_country']??'')));if(!SPF_Country_Registry::exists($country)){add_settings_error('spf_settings','spf_invalid_country',__('El país seleccionado no está soportado.','sistema-para-farmacias'));return;}update_option(SPF_Config::COUNTRY_OPTION,$country);add_settings_error('spf_settings','spf_country_saved',__('País guardado correctamente.','sistema-para-farmacias'),'updated');}if(isset($_POST['spf_save_series'])){if(!$this->can_settings()){wp_die(esc_html__('No tienes permisos para cambiar esta configuración.','sistema-para-farmacias'));}check_admin_referer('spf_save_series');foreach(SPF_Config::sales_documents() as $code=>$meta){$raw=strtoupper(sanitize_text_field(wp_unslash($_POST['series'][$code]??'')));if($raw!==''&&preg_match('/^[A-Z0-9-]{1,20}$/',$raw)){update_option(SPF_Config::document_series_option_key($code),$raw);}}add_settings_error('spf_settings','spf_series_saved',__('Series guardadas correctamente.','sistema-para-farmacias'),'updated');}if(isset($_POST['spf_save_branding'])){if(!$this->can_settings()){wp_die(esc_html__('No tienes permisos para cambiar esta configuración.','sistema-para-farmacias'));}check_admin_referer('spf_save_branding');update_option(SPF_Login_Branding::OPTION,isset($_POST['spf_brand_login'])?'1':'0');add_settings_error('spf_settings','spf_branding_saved',__('Preferencias de acceso guardadas.','sistema-para-farmacias'),'updated');}}
 public function render_dashboard(){include SPF_PLUGIN_DIR.'admin/views/dashboard.php';} public function render_products(){include SPF_PLUGIN_DIR.'admin/views/products.php';} public function render_inventory(){include SPF_PLUGIN_DIR.'admin/views/inventory.php';} public function render_pos(){if(!current_user_can(SPF_Roles::SELL)&&!current_user_can('manage_options')){wp_die(esc_html__('No tienes permisos para usar el punto de venta.','sistema-para-farmacias'));}include SPF_PLUGIN_DIR.'admin/views/pos.php';} public function render_sales(){include SPF_PLUGIN_DIR.'admin/views/sales.php';} public function render_customers(){include SPF_PLUGIN_DIR.'admin/views/customers.php';} public function render_documents(){include SPF_PLUGIN_DIR.'admin/views/documents.php';} public function render_roles(){include SPF_PLUGIN_DIR.'admin/views/roles.php';} public function render_settings(){if(!$this->can_settings()){return;}include SPF_PLUGIN_DIR.'admin/views/settings.php';}
}
